import type { CommonFontOptions, FontResult } from "./types";

export type { Font, FontWithVariable, FontDisplay } from "./types";

/** Options of a Google font loader. Calls are compiled at build time, so every value must be a literal. */
export interface GoogleFontOptions extends CommonFontOptions {
  /** `"400"`, `["400", "700"]` or `"variable"`. Omitted: the variable weight axis, or 400 for static fonts. */
  weight?: string | number | ReadonlyArray<string | number>;
  style?: "normal" | "italic" | ReadonlyArray<"normal" | "italic">;
  /** Unicode subsets to include, e.g. `["latin"]`. Fonts are preloaded only when subsets are given. */
  subsets?: readonly string[];
  axes?: readonly string[];
}

/** Downloads the family at build time and serves it from the app. */
export type GoogleFont = <const T extends GoogleFontOptions = {}>(options?: T) => FontResult<T>;

